// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.19;

import "./interfaces/IERC721State.sol";
import "./interfaces/IERC721Common.sol";
import "./refs/ERC721Nonce.sol";
import "./ERC721PresetMinterPauserAutoIdCustomized.sol";

abstract contract ERC721Common is
    ERC721Nonce,
    ERC721PresetMinterPauserAutoIdCustomized,
    IERC721State,
    IERC721Common
{
    constructor(
        string memory name,
        string memory symbol,
        string memory baseTokenURI
    ) ERC721PresetMinterPauserAutoIdCustomized(name, symbol, baseTokenURI) {}

    /// @inheritdoc IERC721State
    function stateOf(
        uint256 _tokenId
    ) external view virtual override returns (bytes memory) {
        require(
            _exists(_tokenId),
            "ERC721Common: query for non-existent token"
        );
        return abi.encodePacked(ownerOf(_tokenId), nonces[_tokenId], _tokenId);
    }

    /**
     * @dev Override `ERC721-_baseURI`.
     */
    function _baseURI()
        internal
        view
        virtual
        override(ERC721, ERC721PresetMinterPauserAutoIdCustomized)
        returns (string memory)
    {
        return super._baseURI();
    }

    /**
     * @dev Override `IERC165-supportsInterface`.
     */
    function supportsInterface(
        bytes4 interfaceId
    )
        public
        view
        virtual
        override(ERC721, ERC721PresetMinterPauserAutoIdCustomized)
        returns (bool)
    {
        return
            interfaceId == type(IERC721Common).interfaceId ||
            interfaceId == type(IERC721State).interfaceId ||
            super.supportsInterface(interfaceId);
    }

    /**
     * @dev Override `ERC721PresetMinterPauserAutoIdCustomized-_beforeTokenTransfer`.
     */
    function _beforeTokenTransfer(
        address _from,
        address _to,
        uint256 _firstTokenId,
        uint256 _batchSize
    )
        internal
        virtual
        override(ERC721Nonce, ERC721PresetMinterPauserAutoIdCustomized)
    {
        super._beforeTokenTransfer(_from, _to, _firstTokenId, _batchSize);
    }

    /**
     * @dev Bulk create new tokens for `_recipients`. Tokens ID will be automatically
     * assigned (and available on the emitted {IERC721-Transfer} event), and the token
     * URI autogenerated based on the base URI passed at construction.
     *
     * See {ERC721-_mint}.
     *
     * Requirements:
     *
     * - the caller must have the `MINTER_ROLE`.
     */
    function bulkMint(
        address[] calldata _recipients
    )
        external
        virtual
        onlyRole(MINTER_ROLE)
        returns (uint256[] memory _tokenIds)
    {
        require(_recipients.length > 0, "ERC721Common: invalid array lengths");
        _tokenIds = new uint256[](_recipients.length);

        for (uint256 _i = 0; _i < _recipients.length; _i++) {
            _tokenIds[_i] = _mintFor(_recipients[_i]);
        }
    }
}

contracts/ERC721PresetMinterPauserAutoId.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Burnable.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Pausable.sol";
import "@openzeppelin/contracts/access/AccessControlEnumerable.sol";
import "@openzeppelin/contracts/utils/Context.sol";
import "@openzeppelin/contracts/utils/Counters.sol";
import "./interfaces/IERC721PresetMinterPauserAutoIdCustomized.sol";

/**
 * @dev ERC721PresetMinterPauserAutoId is a customized version of
 * openzeppelin/contracts/token/ERC721/presets/ERC721PresetMinterPauserAutoId.sol to change the private counter and
 * base token URI into internal, mainly to support the inherited contracts.
 */
contract ERC721PresetMinterPauserAutoIdCustomized is
    Context,
    AccessControlEnumerable,
    ERC721Enumerable,
    ERC721Burnable,
    ERC721Pausable
{
    using Counters for Counters.Counter;

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    Counters.Counter internal _tokenIdTracker;

    string internal _baseTokenURI;

    /**
     * @dev Grants `DEFAULT_ADMIN_ROLE`, `MINTER_ROLE` and `PAUSER_ROLE` to the
     * account that deploys the contract.
     *
     * Token URIs will be autogenerated based on `baseURI` and their token IDs.
     * See {ERC721-tokenURI}.
     */
    constructor(
        string memory name,
        string memory symbol,
        string memory baseTokenURI
    ) ERC721(name, symbol) {
        _baseTokenURI = baseTokenURI;

        _setupRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _setupRole(MINTER_ROLE, _msgSender());
        _setupRole(PAUSER_ROLE, _msgSender());

        // Token id should start from 1.
        _tokenIdTracker.increment();
    }

    function setBaseURI(
        string memory baseTokenURI
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _baseTokenURI = baseTokenURI;
    }

    function _baseURI() internal view virtual override returns (string memory) {
        return _baseTokenURI;
    }

    /**
     * @dev Creates a new token for `to`. Its token ID will be automatically
     * assigned (and available on the emitted {IERC721-Transfer} event), and the token
     * URI autogenerated based on the base URI passed at construction.
     *
     * See {ERC721-_mint}.
     *
     * Requirements:
     *
     * - the caller must have the `MINTER_ROLE`.
     */
    function mint(address to) public virtual returns (uint256 _tokenId) {
        require(
            hasRole(MINTER_ROLE, _msgSender()),
            "ERC721PresetMinterPauserAutoId: must have minter role to mint"
        );
        return _mintFor(to);
    }

    /**
     * @dev Pauses all token transfers.
     *
     * See {ERC721Pausable} and {Pausable-_pause}.
     *
     * Requirements:
     *
     * - the caller must have the `PAUSER_ROLE`.
     */
    function pause() public virtual {
        require(
            hasRole(PAUSER_ROLE, _msgSender()),
            "ERC721PresetMinterPauserAutoId: must have pauser role to pause"
        );
        _pause();
    }

    /**
     * @dev Unpauses all token transfers.
     *
     * See {ERC721Pausable} and {Pausable-_unpause}.
     *
     * Requirements:
     *
     * - the caller must have the `PAUSER_ROLE`.
     */
    function unpause() public virtual {
        require(
            hasRole(PAUSER_ROLE, _msgSender()),
            "ERC721PresetMinterPauserAutoId: must have pauser role to unpause"
        );
        _unpause();
    }

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 firstTokenId,
        uint256 batchSize
    ) internal virtual override(ERC721, ERC721Enumerable, ERC721Pausable) {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);
    }

    /**
     * @dev See {IERC165-supportsInterface}.
     */
    function supportsInterface(
        bytes4 interfaceId
    )
        public
        view
        virtual
        override(AccessControlEnumerable, ERC721, ERC721Enumerable)
        returns (bool)
    {
        return
            interfaceId ==
            type(IERC721PresetMinterPauserAutoIdCustomized).interfaceId ||
            super.supportsInterface(interfaceId);
    }

    /**
     * @dev Helper function to mint for address `to`.
     *
     * See {ERC721-_mint}.
     *
     */
    function _mintFor(address to) internal virtual returns (uint256 _tokenId) {
        // We cannot just use balanceOf to create the new tokenId because tokens
        // can be burned (destroyed), so we need a separate counter.
        _tokenId = _tokenIdTracker.current();
        _mint(to, _tokenId);
        _tokenIdTracker.increment();
    }
}

