// @@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
// @@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
//
// Runiverse Land Plots
// Website: https://runiverse.world
//
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./ERC721Common.sol";
import "./IRuniverseLand.sol";

/**
 * @dev This implements the total set of plots in the Runiverse. The plots are
 * {ERC721} tokens.
 *
 * This contract itself is not upgradable and the tokens have a fixed supply, but the
 * minting mechanism is flexible.
 *
 * Because the totally supply of land will be minted in phases over a long
 * period of time, this contract is designed to mint through companion
 * contracts, as specified by primaryMinter and secondaryMinter.
 *
 * We specify both a primary and a secondary minter because it allows for atomic
 * upgrades without downtime.
 */
contract RuniverseLand is
    ERC721Common,
    Ownable,
    ReentrancyGuard,
    IRuniverseLand
{
    using Strings for uint256;

    /// @notice Maximum supply of land plots
    uint256 private constant MAX_SUPPLY = 70000;

    /// @notice Counter to track the number minted so far
    uint256 public numMinted;

    /// @notice Address of the primary minter
    address public primaryMinter;

    /// @notice Address of the secondary minter
    address public secondaryMinter;

    /// @notice The base URI for the metadata of the tokens
    string public baseTokenURI;

    error NoPlotsAvailable();
    error Address0Error();

    /// @notice Whitelist for markets
    mapping(address => bool) private _deniedMarketplaces;

    // VESTABLE OPTIONS

    /// @notice master switch for vesting
    uint256 public vestingEnabled = 1;

    /// @notice the tokens from 0 to lastVestedTokenId will vest over time
    uint256 public lastVestingGlobalId = 10924;

    /// @notice the time the vesting started
    uint256 public vestingStart = 1674172801; // Jan 20th, 2023. 23:59 gmt

    /// @notice the time the vesting ends
    uint256 public vestingEnd = 1737331201; // Jan 20th, 2025. 23:59 gmt

    /// Invalid Vesting Global Id, the gived Global ID : "`gived_global_id`" must be greater than 0
    /// @param gived_global_id Global id.
    error InvalidVestingGlobalId(uint256 gived_global_id);

    /// Token Not Vested, The Vesting date is the next one `gived_global_id`
    /// @param current_time Current time on chain.
    /// @param token_vesting_time Vesting time.
    error TokenNotVested(uint256 current_time, uint256 token_vesting_time);

    string private constant R = "I should like to save the Shire, if I could";

    /**
     * @dev Create the contract and set the initial baseURI
     * @param baseURI string the initial base URI for the token metadata URL
     */
    constructor(
        string memory baseURI
    ) ERC721Common("RuniverseLand", "RUNIVERSE", baseURI) {
        baseTokenURI = baseURI;
        _baseTokenURI = baseURI;
    }

    /**
     * @dev Pause contract.
     */
    function pauseContract() external onlyOwner {
        if (!this.paused()) {
            _pause();
        }
    }

    /**
     * @dev Unpause contract.
     */
    function unpauseContract() external onlyOwner {
        if (this.paused()) {
            _unpause();
        }
    }

    /**
     * @dev Overrides _beforeTokenTransfer
     * see {https://docs.openzeppelin.com/contracts/4.x/api/token/erc721#ERC721-_beforeTokenTransfer-address-address-uint256-uint256-}.
     */
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 firstTokenId,
        uint256 batchSize
    ) internal override(ERC721Common) {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);
        uint256 globalId = getGlobalId(firstTokenId);
        if (
            vestingEnabled == 1 &&
            from != address(0) && // minting
            globalId <= lastVestingGlobalId &&
            block.timestamp < vestingEnd
        ) {
            uint256 vestingDuration = vestingEnd - vestingStart;

            if (
                block.timestamp <
                (vestingDuration * globalId) /
                    lastVestingGlobalId +
                    vestingStart
            ) {
                revert TokenNotVested({
                    current_time: block.timestamp,
                    token_vesting_time: (vestingDuration * globalId) /
                        lastVestingGlobalId +
                        vestingStart
                });
            }
        }
    }

    /**
     *
     * @param ownerAddress address of owner.
     * @return tokensOwned uint256 with IDs of owned tokens.
     */
    function getTokens(
        address ownerAddress
    ) public view returns (uint256[] memory) {
        uint256 numTokensOwned = this.balanceOf(ownerAddress);
        uint256[] memory tokensOwned = new uint256[](numTokensOwned);

        for (uint256 index = 0; index < numTokensOwned; index++) {
            tokensOwned[index] = this.tokenOfOwnerByIndex(ownerAddress, index);
        }

        return tokensOwned;
    }

    /**
     * @notice returns true if a tokenId has besting property.
     */
    function isVestingToken(uint256 tokenId) external view returns (bool) {
        uint256 globalId = getGlobalId(tokenId);
        return globalId <= lastVestingGlobalId;
    }

    /**
     * @notice returns the time when a tokenId will be vested.
     */
    function vestsAt(uint256 tokenId) public view returns (uint256) {
        uint256 globalId = getGlobalId(tokenId);
        uint256 vestingDuration = vestingEnd - vestingStart;
        return
            (vestingDuration * globalId) / lastVestingGlobalId + vestingStart;
    }

    /**
     * @notice returns true if a tokenId is already vested.
     */
    function isVested(uint256 tokenId) public view returns (bool) {
        uint256 globalId = getGlobalId(tokenId);
        if (vestingEnabled == 0) return true;
        if (globalId > lastVestingGlobalId) return true;
        if (block.timestamp > vestingEnd) return true;
        return block.timestamp >= vestsAt(tokenId);
    }

    /**
     * @notice set the vesting toggle
     */
    function _setVestingEnabled(uint256 _newVestingEnabled) internal virtual {
        vestingEnabled = _newVestingEnabled;
    }

    /**
     * @notice set the last vesting token Id
     */
    function _setLastVestingGlobalId(uint256 _newTokenId) internal virtual {
        if (_newTokenId <= 0) {
            revert InvalidVestingGlobalId({gived_global_id: _newTokenId});
        }
        lastVestingGlobalId = _newTokenId;
    }

    /**
     * @notice set the new vesting start time
     */
    function _setVestingStart(uint256 _newVestingStart) internal virtual {
        require(_newVestingStart < vestingEnd, "Start must be less than end");
        vestingStart = _newVestingStart;
    }

    /**
     * @notice set the new vesting start time
     */
    function _setVestingEnd(uint256 _newVestingEnd) internal virtual {
        require(
            _newVestingEnd > vestingStart,
            "End must be greater than start"
        );
        vestingEnd = _newVestingEnd;
    }

    /**
     * @notice extracts global id from token id
     */
    function getGlobalId(uint256 tokenId) public pure returns (uint256) {
        return tokenId >> 40;
    }

    /**
     * @notice Mint a new token with a specific id
     * @param recipient address representing the owner of the new tokenId
     * @param tokenId uint256 ID of the token to be minted
     * @param size PlotSize size to be minted.
     */
    function mintTokenId(
        address recipient,
        uint256 tokenId,
        PlotSize size
    ) public override nonReentrant {
        if (numMinted >= MAX_SUPPLY) {
            revert NoPlotsAvailable();
        }
        require(
            _msgSender() == primaryMinter || _msgSender() == secondaryMinter,
            "Not a minter"
        );
        ++numMinted;
        emit LandMinted(recipient, tokenId, size);

        _mint(recipient, tokenId);
    }

    /**
     * @dev Returns the URL of a given tokenId
     * @param tokenId uint256 ID of the token to be minted
     * @return string the URL of a given tokenId
     */
    function tokenURI(
        uint256 tokenId
    ) public view virtual override returns (string memory) {
        require(
            _exists(tokenId),
            "ERC721Metadata: URI query for nonexistent token"
        );

        return string(abi.encodePacked(baseTokenURI, tokenId.toString()));
    }

    /**
     * @dev Returns if the token exists
     * @param tokenId uint256 the id of the token
     * @return exists bool if it exists
     */
    function exists(uint256 tokenId) external view returns (bool) {
        return _exists(tokenId);
    }

    /**
     * @dev Returns the base uri of the token.
     * @return _baseURI string prefix uri.
     */
    function _baseURI() internal view virtual override returns (string memory) {
        return baseTokenURI;
    }

    /**
     * @dev Returns the total number of minted lands.
     * @return totalSupply uint256 the number of minted lands.
     */
    function totalSupply()
        public
        view
        override(ERC721Enumerable)
        returns (uint256)
    {
        return numMinted;
    }

    /**
     * @dev Returns the base URI of the token.
     * @return baseTokenURI String value of base Token URI.
     */
    function getBaseURI() external view returns (string memory) {
        return baseTokenURI;
    }

    /**
     * Only the owner can do these things
     */

    /**
     * @dev Sets a new base URI
     * @param newBaseURI string the new token base URI
     */
    function setNewBaseURI(string calldata newBaseURI) public onlyOwner {
        baseTokenURI = newBaseURI;
        _baseTokenURI = newBaseURI;
    }

    /**
     * @dev Sets a new primary minter address
     * @param newPrimaryMinter address of the new minter
     */
    function setPrimaryMinter(address newPrimaryMinter) external onlyOwner {
        require(
            newPrimaryMinter != address(0),
            "Invalid primary minter address"
        );
        primaryMinter = newPrimaryMinter;
    }

    /**
     * @dev Sets a new secondary minter address
     * @param newSecondaryMinter address of the new secondary minter
     */
    function setSecondaryMinter(address newSecondaryMinter) external onlyOwner {
        require(
            newSecondaryMinter != address(0),
            "Invalid seecondary minter address"
        );
        secondaryMinter = newSecondaryMinter;
    }

    /**
     * @notice set the vesting toggle
     * @param _newVestingEnabled 1 for true, 0 for false
     */
    function setVestingEnabled(uint256 _newVestingEnabled) external onlyOwner {
        _setVestingEnabled(_newVestingEnabled);
    }

    /**
     * @notice set the last vesting token Id
     */
    function setLastVestingGlobalId(uint256 _newTokenId) external onlyOwner {
        _setLastVestingGlobalId(_newTokenId);
    }

    /**
     * @notice set the new vesting start time
     */
    function setVestingStart(uint256 _newVestingStart) external onlyOwner {
        _setVestingStart(_newVestingStart);
    }

    /**
     * @notice set the new vesting end time
     */
    function setVestingEnd(uint256 _newVestingEnd) external onlyOwner {
        _setVestingEnd(_newVestingEnd);
    }

    /**
     * @notice Override of the approve method to blacklist markets
     * @param to address to approve transfer
     * @param tokenId token be transferred allowed by to
     */
    function approve(
        address to,
        uint256 tokenId
    ) public virtual override(IERC721, ERC721) {
        require(!_deniedMarketplaces[to], "Invalid Marketplace");
        super.approve(to, tokenId);
    }

    /**
     * @notice Override of the setApprovalForAll method to blacklist markets
     * @param operator address to approve transfer
     * @param approved enable or disable transfer
     */
    function setApprovalForAll(
        address operator,
        bool approved
    ) public virtual override(IERC721, ERC721) {
        require(!_deniedMarketplaces[operator], "Invalid Marketplace");
        super.setApprovalForAll(operator, approved);
    }

    /**
     * @notice Override of the isApprovedForAll method to blacklist markets. Reverts if is not allowed.
     * @param owner owner of the tokens
     * @param operator marketplace address
     * @return true if all the tokens are approved to be trasnferred by operator.
     */
    function isApprovedForAll(
        address owner,
        address operator
    ) public view virtual override(IERC721, ERC721) returns (bool) {
        require(!_deniedMarketplaces[operator], "Invalid Marketplace");
        return super.isApprovedForAll(owner, operator);
    }

    /**
     * @notice Override of the getApproved method to blacklist markets. Reverts if is not allowed.
     * @param tokenId Id of the token to check if is approved.
     * @return address that is allowed to transfer the tokenId
     */
    function getApproved(
        uint256 tokenId
    ) public view virtual override(IERC721, ERC721) returns (address) {
        address addr = super.getApproved(tokenId);
        require(!_deniedMarketplaces[addr], "Invalid Marketplace");
        return addr;
    }

    /**
     * @notice Add or remove an address for the market blacklist
     * @param market market place address
     * @param denied deny (true) or allow (false) a marketplace
     */
    function setDeniedMarketplace(
        address market,
        bool denied
    ) public onlyOwner {
        _deniedMarketplaces[market] = denied;
    }

    /**
     * @dev ETH should not be sent to this contract, but in the case that it is
     * sent by accident, this function allows the owner to withdraw it.
     */
    function withdrawAll() external payable onlyOwner {
        (bool success, ) = msg.sender.call{value: address(this).balance}("");
        require(success, "withdraw was not succesfull");
    }

    /**
     * @dev Again, ERC20s should not be sent to this contract, but if someone
     * does, it's nice to be able to recover them
     * @param token IERC20 the token address
     * @param amount uint256 the amount to send
     */
    function forwardERC20s(IERC20 token, uint256 amount) external onlyOwner {
        if (address(msg.sender) == address(0)) {
            revert Address0Error();
        }
        token.transfer(msg.sender, amount);
    }
}

contracts/RuniverseLandMinter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./IRuniverseLand.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/draft-EIP712.sol";
import "@openzeppelin/contracts/utils/Address.sol";

contract RuniverseLandMinter is Ownable, ReentrancyGuard {
    using Address for address payable;

    /// @notice Address to the ERC721 RuniverseLand contract
    IRuniverseLand public runiverseLand;

    /// @notice Address to the vault where we can withdraw
    address payable public vault;

    uint256[] plotsAvailablePerSize = [
        52500, // 8x8
        16828, // 16x16
        560, // 32x32
        105, // 64x64
        7 // 128x128
    ];

    uint256[] public plotSizeLocalOffset = [
        1, // 8x8
        1, // 16x16
        1, // 32x32
        1, // 64x64
        1 // 128x128
    ];

    uint256 public plotGlobalOffset = 1;

    uint256[] public plotPrices = [
        type(uint256).max,
        type(uint256).max,
        type(uint256).max,
        type(uint256).max,
        type(uint256).max
    ];

    uint256 public publicMintStartTime = type(uint256).max;
    uint256 public mintlistStartTime = type(uint256).max;
    uint256 public claimsStartTime = type(uint256).max;

    /// @notice The primary merkle root
    bytes32 public mintlistMerkleRoot1;

    /// @notice The secondary Merkle root
    bytes32 public mintlistMerkleRoot2;

    /// @notice The claimslist Merkle root
    bytes32 public claimlistMerkleRoot;

    /// @notice stores the number actually minted per plot size
    mapping(uint256 => uint256) public plotsMinted;

    /// @notice stores the number minted by this address in the mintlist by size
    mapping(address => mapping(uint256 => uint256))
        public mintlistMintedPerSize;

    /// @notice stores the number minted by this address in the claimslist by size
    mapping(address => mapping(uint256 => uint256))
        public claimlistMintedPerSize;

    /**
     * @dev Create the contract and set the initial baseURI
     * @param _runiverseLand address the initial base URI for the token metadata URL
     */
    constructor(IRuniverseLand _runiverseLand) {
        setRuniverseLand(_runiverseLand);
        setVaultAddress(payable(msg.sender));
    }

    /**
     * @dev returns true if the whitelisted mintlist started.
     * @return mintlistStarted true if mintlist started.
     */
    function mintlistStarted() public view returns (bool) {
        return block.timestamp >= mintlistStartTime;
    }

    /**
     * @dev returns true if the whitelisted claimlist started.
     * @return mintlistStarted true if claimlist started.
     */
    function claimsStarted() public view returns (bool) {
        return block.timestamp >= claimsStartTime;
    }

    /**
     * @dev returns true if the public minting started.
     * @return mintlistStarted true if public minting started.
     */
    function publicStarted() public view returns (bool) {
        return block.timestamp >= publicMintStartTime;
    }

    /**
     * @dev returns how many plots were avialable since the begining.
     * @return getPlotsAvailablePerSize array uint256 of 5 elements.
     */
    function getPlotsAvailablePerSize()
        external
        view
        returns (uint256[] memory)
    {
        return plotsAvailablePerSize;
    }

    /**
     * @dev returns the eth cost of each plot.
     * @return getPlotPrices array uint256 of 5 elements.
     */
    function getPlotPrices() external view returns (uint256[] memory) {
        return plotPrices;
    }

    /**
     * @dev returns the plot type of a token id.
     * @param tokenId uint256 token id.
     * @return getPlotPrices uint256 plot type.
     */
    function getTokenIdPlotType(
        uint256 tokenId
    ) external pure returns (uint256) {
        return tokenId & 255;
    }

    /**
     * @dev return the total number of minted plots
     * @return getTotalMintedLands uint256 number of minted plots.
     */
    function getTotalMintedLands() external view returns (uint256) {
        uint256 totalMintedLands;
        totalMintedLands =
            plotsMinted[0] +
            plotsMinted[1] +
            plotsMinted[2] +
            plotsMinted[3] +
            plotsMinted[4];
        return totalMintedLands;
    }

    /**
     * @dev return the total number of minted plots of each size.
     * @return getTotalMintedLandsBySize array uint256 number of minted plots of each size.
     */

    function getTotalMintedLandsBySize()
        external
        view
        returns (uint256[] memory)
    {
        uint256[] memory plotsMintedBySize = new uint256[](5);

        plotsMintedBySize[0] = plotsMinted[0];
        plotsMintedBySize[1] = plotsMinted[1];
        plotsMintedBySize[2] = plotsMinted[2];
        plotsMintedBySize[3] = plotsMinted[3];
        plotsMintedBySize[4] = plotsMinted[4];

        return plotsMintedBySize;
    }

    /**
     * @dev returns the number of plots left of each size.
     * @return getAvailableLands array uint256 of 5 elements.
     */
    function getAvailableLands() external view returns (uint256[] memory) {
        uint256[] memory plotsAvailableBySize = new uint256[](5);

        plotsAvailableBySize[0] = plotsAvailablePerSize[0] - plotsMinted[0];
        plotsAvailableBySize[1] = plotsAvailablePerSize[1] - plotsMinted[1];
        plotsAvailableBySize[2] = plotsAvailablePerSize[2] - plotsMinted[2];
        plotsAvailableBySize[3] = plotsAvailablePerSize[3] - plotsMinted[3];
        plotsAvailableBySize[4] = plotsAvailablePerSize[4] - plotsMinted[4];

        return plotsAvailableBySize;
    }

    /**
     * @dev mint public method to mint when the whitelist (mintlist) is active.
     * @param _who address address that is minting.
     * @param _leaf bytes32 merkle leaf.
     * @param _merkleProof bytes32[] merkle proof.
     * @return mintlisted bool success mint.
     */
    function mintlisted(
        address _who,
        bytes32 _leaf,
        bytes32[] calldata _merkleProof
    ) external view returns (bool) {
        bytes32 node = keccak256(abi.encodePacked(_who));

        if (node != _leaf) return false;
        if (
            MerkleProof.verify(_merkleProof, mintlistMerkleRoot1, _leaf) ||
            MerkleProof.verify(_merkleProof, mintlistMerkleRoot2, _leaf)
        ) {
            return true;
        }
        return false;
    }

    /**
     * @dev public method  for public minting.
     * @param plotSize PlotSize enum with plot size.
     * @param numPlots uint256 number of plots to be minted.
     */
    function mint(
        IRuniverseLand.PlotSize plotSize,
        uint256 numPlots
    ) external payable nonReentrant {
        if (!publicStarted()) {
            revert WrongDateForProcess({
                correct_date: publicMintStartTime,
                current_date: block.timestamp
            });
        }
        if (numPlots <= 0 && numPlots > 20) {
            revert IncorrectPurchaseLimit();
        }
        _mintTokensCheckingValue(plotSize, numPlots, msg.sender);
    }

    /**
     * @dev public method to mint when the whitelist (mintlist) is active.
     * @param plotSize PlotSize enum with plot size.
     * @param numPlots uint256 number of plots to be minted.
     * @param claimedMaxPlots uint256 maximum number of plots of plotSize size  that the address mint.
     * @param _merkleProof bytes32[] merkle proof.
     */
    function mintlistMint(
        IRuniverseLand.PlotSize plotSize,
        uint256 numPlots,
        uint256 claimedMaxPlots,
        bytes32[] calldata _merkleProof
    ) external payable nonReentrant {
        if (!mintlistStarted()) {
            revert WrongDateForProcess({
                correct_date: mintlistStartTime,
                current_date: block.timestamp
            });
        }
        if (numPlots <= 0 && numPlots > 20) {
            revert IncorrectPurchaseLimit();
        }
        // verify allowlist
        bytes32 _leaf = keccak256(
            abi.encodePacked(
                msg.sender,
                ":",
                uint256(plotSize),
                ":",
                claimedMaxPlots
            )
        );

        require(
            MerkleProof.verify(_merkleProof, mintlistMerkleRoot1, _leaf) ||
                MerkleProof.verify(_merkleProof, mintlistMerkleRoot2, _leaf),
            "Invalid proof."
        );

        mapping(uint256 => uint256)
            storage mintedPerSize = mintlistMintedPerSize[msg.sender];

        require(
            mintedPerSize[uint256(plotSize)] + numPlots <= claimedMaxPlots, // this is verified by the merkle proof
            "Minting more than allowed"
        );
        mintedPerSize[uint256(plotSize)] += numPlots;
        _mintTokensCheckingValue(plotSize, numPlots, msg.sender);
    }

    /**
     * @dev public method to claim a plot, only when (claimlist) is active.
     * @param plotSize PlotSize enum with plot size.
     * @param numPlots uint256 number of plots to be minted.
     * @param claimedMaxPlots uint256 maximum number of plots of plotSize size  that the address mint.
     * @param _merkleProof bytes32[] merkle proof.
     */
    function claimlistMint(
        IRuniverseLand.PlotSize plotSize,
        uint256 numPlots,
        uint256 claimedMaxPlots,
        bytes32[] calldata _merkleProof
    ) external payable nonReentrant {
        if (!claimsStarted()) {
            revert WrongDateForProcess({
                correct_date: claimsStartTime,
                current_date: block.timestamp
            });
        }

        // verify allowlist
        bytes32 _leaf = keccak256(
            abi.encodePacked(
                msg.sender,
                ":",
                uint256(plotSize),
                ":",
                claimedMaxPlots
            )
        );

        require(
            MerkleProof.verify(_merkleProof, claimlistMerkleRoot, _leaf),
            "Invalid proof."
        );

        mapping(uint256 => uint256)
            storage mintedPerSize = claimlistMintedPerSize[msg.sender];

        require(
            mintedPerSize[uint256(plotSize)] + numPlots <= claimedMaxPlots, // this is verified by the merkle proof
            "Claiming more than allowed"
        );
        mintedPerSize[uint256(plotSize)] += numPlots;
        _mintTokens(plotSize, numPlots, msg.sender);
    }

    /**
     * @dev checks if the amount sent is correct. Continue minting if it is correct.
     * @param plotSize PlotSize enum with plot size.
     * @param numPlots uint256 number of plots to be minted.
     * @param recipient address  address that sent the mint.
     */
    function _mintTokensCheckingValue(
        IRuniverseLand.PlotSize plotSize,
        uint256 numPlots,
        address recipient
    ) private {
        if (plotPrices[uint256(plotSize)] <= 0) {
            revert MisconfiguredPrices();
        }
        require(
            msg.value == plotPrices[uint256(plotSize)] * numPlots,
            "Ether value sent is not accurate"
        );
        _mintTokens(plotSize, numPlots, recipient);
    }

    /**
     * @dev checks if there are plots available. Final step before sending it to RuniverseLand contract.
     * @param plotSize PlotSize enum with plot size.
     * @param numPlots uint256 number of plots to be minted.
     * @param recipient address  address that sent the mint.
     */
    function _mintTokens(
        IRuniverseLand.PlotSize plotSize,
        uint256 numPlots,
        address recipient
    ) private {
        require(
            plotsMinted[uint256(plotSize)] + numPlots <=
                plotsAvailablePerSize[uint256(plotSize)],
            "Trying to mint too many plots"
        );

        for (uint256 i; i < numPlots; ++i) {
            uint256 tokenId = ownerGetNextTokenId(plotSize);
            ++plotsMinted[uint256(plotSize)];

            runiverseLand.mintTokenId(recipient, tokenId, plotSize);
        }
    }

    /**
     * @dev Method to mint many plot and assign it to an addresses without any requirement. Used for private minting.
     * @param plotSizes PlotSize[] enums with plot sizes.
     * @param recipients address[]  addresses where the token will be transferred.
     */
    function ownerMint(
        IRuniverseLand.PlotSize[] calldata plotSizes,
        address[] calldata recipients
    ) external onlyOwner {
        require(
            plotSizes.length == recipients.length,
            "Arrays should have the same size"
        );
        for (uint256 i; i < recipients.length; ++i) {
            _mintTokens(plotSizes[i], 1, recipients[i]);
        }
    }

    /**
     * @dev Encodes the next token id.
     * @param plotSize PlotSize enum with plot size.
     * @return ownerGetNextTokenId uint256 encoded next toknId.
     */
    function ownerGetNextTokenId(
        IRuniverseLand.PlotSize plotSize
    ) private view returns (uint256) {
        uint256 globalCounter = plotsMinted[0] +
            plotsMinted[1] +
            plotsMinted[2] +
            plotsMinted[3] +
            plotsMinted[4] +
            plotGlobalOffset;
        uint256 localCounter = plotsMinted[uint256(plotSize)] +
            plotSizeLocalOffset[uint256(plotSize)];
        require(localCounter <= 4294967295, "Local index overflow");
        require(uint256(plotSize) <= 255, "Plot index overflow");

        return (globalCounter << 40) + (localCounter << 8) + uint256(plotSize);
    }

    /**
     * Owner Controls
     */
    /**
     * @dev Assigns a new public start minting time.
     * @param _newPublicMintStartTime uint256 echo time in seconds.
     */
    function setPublicMintStartTime(
        uint256 _newPublicMintStartTime
    ) external onlyOwner {
        publicMintStartTime = _newPublicMintStartTime;
    }

    /**
     * @dev Assigns a new mintlist start minting time.
     * @param _newAllowlistMintStartTime uint256 echo time in seconds.
     */
    function setMintlistStartTime(
        uint256 _newAllowlistMintStartTime
    ) external onlyOwner {
        mintlistStartTime = _newAllowlistMintStartTime;
    }

    /**
     * @dev Assigns a new claimlist start minting time.
     * @param _newClaimsStartTime uint256 echo time in seconds.
     */
