     */
    function setGlobalIdOffset(uint256 _newGlobalIdOffset) external onlyOwner {
        if (mintlistStarted()) {
            revert DeniedProcessDuringMinting();
        }
        plotGlobalOffset = _newGlobalIdOffset;
    }

    /**
